)

// Expression is an expression template
// that can interpolate to some variables
type Expression struct {
	// namespace is expression namespace,
	// e.g. internal.traits has a variable traits
	// in internal namespace
	namespace string
	// variable is a variable name, e.g. trait name,
	// e.g. internal.traits has variable name traits
	variable string
	// prefix is a prefix of the string
	prefix string
	// suffix is a suffix
	suffix string
	// transform is an optional transformer for the variable.
	transform transformer
}

// emailLocalTransformer extracts local part of the email.
type emailLocalTransformer struct{}

// EmailLocal returns local part of the email
func (emailLocalTransformer) transform(in string) (string, error) {
	if in == "" {
		return "", trace.BadParameter("address is empty")
	}
	addr, err := mail.ParseAddress(in)
	if err != nil {
		return "", trace.BadParameter("failed to parse address %q: %q", in, err)
	}
	parts := strings.SplitN(addr.Address, "@", 2)
	if len(parts) != 2 {
		return "", trace.BadParameter("could not find local part in %q", addr.Address)
	}
	return parts[0], nil
}

// Namespace returns a variable namespace, e.g. external or internal
func (p *Expression) Namespace() string {
	return p.namespace
}

// Name returns variable name
func (p *Expression) Name() string {
	return p.variable
}

// Interpolate interpolates the variable adding prefix and suffix if present,
// returns trace.NotFound in case if the trait is not found, nil in case of
// success and BadParameter error otherwise
func (p *Expression) Interpolate(traits map[string][]string) ([]string, error) {
	if p.namespace == LiteralNamespace {
		return []string{p.variable}, nil
	}
	values, ok := traits[p.variable]
	if !ok {
		return nil, trace.NotFound("variable is not found")
	}
	out := make([]string, len(values))
	for i := range values {
		val := values[i]
		var err error
		if p.transform != nil {
			val, err = p.transform.transform(val)
			if err != nil {
				return nil, trace.Wrap(err)
			}
		}
		out[i] = p.prefix + val + p.suffix
	}
	return out, nil
}

var reVariable = regexp.MustCompile(
	// prefix is anyting that is not { or }
	`^(?P<prefix>[^}{]*)` +
		// variable is antything in brackets {{}} that is not { or }
		`{{(?P<expression>\s*[^}{]*\s*)}}` +
		// prefix is anyting that is not { or }
		`(?P<suffix>[^}{]*)$`,
)

// Variable parses expressions like {{external.foo}} or {{internal.bar}}, or a
// literal value like "prod". Call Interpolate on the returned Expression to
// get the final value based on traits or other dynamic values.
func Variable(variable string) (*Expression, error) {
	original := variable
	match := reVariable.FindStringSubmatch(variable)
	if len(match) == 0 {
		if strings.Contains(variable, "{{") || strings.Contains(variable, "}}") {
			return nil, trace.BadParameter(
				"%q is using template brackets '{{' or '}}', however expression does not parse, make sure the format is {{variable}}",
				variable)
		}
		return &Expression{
			namespace: LiteralNamespace,
			variable:  variable,
		}, nil
	}

	prefix, variable, suffix := match[1], match[2], match[3]

	// parse and get the ast of the expression
	expr, err := parser.ParseExpr(variable)
	if err != nil {
		return nil, trace.NotFound("no variable found in %q: %v", variable, err)
	}
	if containsMatcherFunction(expr) {
		return nil, trace.BadParameter("matcher functions (like regexp.match) are not allowed here: %q", original)
	}

	// walk the ast tree and gather the variable parts
	result, err := walk(expr)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// the variable must have two parts the prefix and the variable name itself
	if len(result.parts) != 2 {
		return nil, trace.NotFound("no variable found: %v", variable)
	}

	return &Expression{
		prefix:    strings.TrimLeftFunc(prefix, unicode.IsSpace),
		namespace: result.parts[0],
		variable:  result.parts[1],
		suffix:    strings.TrimRightFunc(suffix, unicode.IsSpace),
		transform: result.transform,
	}, nil
}

// Matcher tests whether a string satisfies a match expression.
type Matcher interface {
	Match(in string) bool
}

type regexpMatcher struct{ regexp *regexp.Regexp }

func (m regexpMatcher) Match(in string) bool { return m.regexp.MatchString(in) }

type prefixSuffixMatcher struct {
	prefix, suffix string
	matcher        Matcher
}

func (m prefixSuffixMatcher) Match(in string) bool {
	if !strings.HasPrefix(in, m.prefix) || !strings.HasSuffix(in, m.suffix) || len(in) < len(m.prefix)+len(m.suffix) {
		return false
	}
	return m.matcher.Match(in[len(m.prefix) : len(in)-len(m.suffix)])
}

type notMatcher struct{ matcher Matcher }

func (m notMatcher) Match(in string) bool { return !m.matcher.Match(in) }

// Match parses a literal, glob, regexp, or a single matcher function in a template.
func Match(value string) (Matcher, error) {
	start := strings.Index(value, "{{")
	end := strings.LastIndex(value, "}}")
	if start < 0 && end < 0 {
		pattern := value
		if !strings.HasPrefix(pattern, "^") || !strings.HasSuffix(pattern, "$") {
			pattern = "^" + utils.GlobToRegexp(pattern) + "$"
		}
		re, err := regexp.Compile(pattern)
		if err != nil {
			return nil, trace.BadParameter("failed parsing regexp %q: %v", value, err)
		}
		return regexpMatcher{regexp: re}, nil
	}
	if start < 0 || end < start+2 || strings.ContainsAny(value[:start], "{}") || strings.ContainsAny(value[end+2:], "{}") {
		return nil, trace.BadParameter("%q is using template brackets '{{' or '}}', however expression does not parse, make sure the format is {{expression}}", value)
	}

	expression := value[start+2 : end]
	expr, err := parser.ParseExpr(expression)
	if err != nil {
		return nil, trace.BadParameter("%q is not a valid matcher expression - no variables and transformations are allowed", expression)
	}
	matcher, err := matcherExpression(expr, expression)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return prefixSuffixMatcher{prefix: value[:start], suffix: value[end+2:], matcher: matcher}, nil
}

func matcherExpression(expr ast.Expr, expression string) (Matcher, error) {
	call, ok := expr.(*ast.CallExpr)
	if !ok {
		return nil, trace.BadParameter("%q is not a valid matcher expression - no variables and transformations are allowed", expression)
	}
	selector, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return nil, trace.BadParameter("%q is not a valid matcher expression - no variables and transformations are allowed", expression)
	}
	namespace, ok := selector.X.(*ast.Ident)
	if !ok {
		return nil, trace.BadParameter("%q is not a valid matcher expression - no variables and transformations are allowed", expression)
	}
	if namespace.Name != "regexp" && namespace.Name != EmailNamespace {
		return nil, trace.BadParameter("unsupported function namespace %s, supported namespaces are email and regexp", namespace.Name)
	}
	name := namespace.Name + "." + selector.Sel.Name
	if namespace.Name == EmailNamespace {
		if selector.Sel.Name != EmailLocalFnName {
			return nil, trace.BadParameter("unsupported function %s, supported functions are: email.local", name)
		}
	} else if selector.Sel.Name != "match" && selector.Sel.Name != "not_match" {
		return nil, trace.BadParameter("unsupported function %s, supported functions are: regexp.match, regexp.not_match.", name)
	}
	if len(call.Args) != 1 {
		return nil, trace.BadParameter("%s requires exactly one string literal argument", name)
	}
	arg, ok := call.Args[0].(*ast.BasicLit)
	if !ok || arg.Kind != token.STRING {
		return nil, trace.BadParameter("%s requires exactly one string literal argument", name)
	}
	raw, err := strconv.Unquote(arg.Value)
	if err != nil {
		return nil, trace.BadParameter("invalid string literal in %s: %v", name, err)
	}
	if namespace.Name == EmailNamespace {
		return nil, trace.BadParameter("%q is not a valid matcher expression - no variables and transformations are allowed", expression)
	}
	re, err := regexp.Compile(raw)
	if err != nil {
		return nil, trace.BadParameter("failed parsing regexp %q: %v", raw, err)
	}
	var matcher Matcher = regexpMatcher{regexp: re}
	if selector.Sel.Name == "not_match" {
		matcher = notMatcher{matcher: matcher}
	}
	return matcher, nil
}

func containsMatcherFunction(expr ast.Expr) bool {
	found := false
	ast.Inspect(expr, func(node ast.Node) bool {
		call, ok := node.(*ast.CallExpr)
		if !ok {
			return true
		}
		selector, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		namespace, ok := selector.X.(*ast.Ident)
		if ok && namespace.Name == "regexp" && (selector.Sel.Name == "match" || selector.Sel.Name == "not_match") {
			found = true
			return false
		}
		return true
	})
	return found
}

const (
	// LiteralNamespace is a namespace for Expressions that always return
	// static literal values.
	LiteralNamespace = "literal"
	// EmailNamespace is a function namespace for email functions
	EmailNamespace = "email"
	// EmailLocalFnName is a name for email.local function
	EmailLocalFnName = "local"
)

// transformer is an optional value transformer function that can take in
// string and replace it with another value
type transformer interface {
	transform(in string) (string, error)
}

type walkResult struct {
	parts     []string
	transform transformer
}

